ans = 0
R = 1
for L in 1..N:
  while (L, R) が条件を満たす:
    R <- R+1
  //(L,L),...(L,R-1)が条件を満たす
  ans <- ans+(R-L)

#include<bits/stdc++.h>
using namespace std;
using ll=long long;

int main(){
	int n,d;
	cin >> n >> d;
	vector<int>a(n);
	for(auto&x:a)cin >> x;

	ll ans=0;
	set<ll>s({(ll)-1e9,(ll)2e9});
	int r=0;
	for(int l=0;l<n;l++){
		while(r<n){
			auto it=s.lower_bound(a[r]);
			if(*it-a[r]<d)break;
			it--;
			if(a[r]-*it<d)break;
			s.insert(a[r]);
			r++;
		}
		ans+=r-l;
		s.erase(a[l]);
	}
	cout << ans << endl;
}
